#!/bin/bash
#SBATCH --account=def-khenni
#SBATCH --job-name=downstream_scoped-s1f4
#SBATCH --time=57:00:00
#SBATCH --cpus-per-task=16
#SBATCH --mem=64G
#SBATCH --output=logs/%x-%j.out
#SBATCH --error=logs/%x-%j.err
#SBATCH --requeue

# Generated by scripts/narval/submit.py. Edit the study config, not this file.

# Repair CRLF endings if the file was touched on Windows.
if grep -q $'\r' "$0" 2>/dev/null; then
  sed -i 's/\r$//' "$0"
  exec bash "$0" "$@"
fi

source "${SLURM_SUBMIT_DIR:-$HOME/eeg_qgan}/scripts/narval/_common.sh"

echo "study downstream_scoped"
echo "args  --seed-index 1 --fold-start 4 --fold-end 5 --set use_gpu=false"

python -m eeg_qgan.experiments.runner downstream_scoped \
  --data-root "$DATA_ROOT" \
  --output-root "$OUTPUT_ROOT" \
  --seed-index 1 --fold-start 4 --fold-end 5 --set use_gpu=false

echo "finished $(date --iso-8601=seconds)"
